#include "PluginEditor.h"

#include <cmath>

namespace {
const auto cream=juce::Colour(0xffe9dfcf),cyan=juce::Colour(0xff35e1dc),amber=juce::Colour(0xffffad32),panel=juce::Colour(0xff171d23),dark=juce::Colour(0xff050b0e);
void screw(juce::Graphics&g,float x,float y){g.setGradientFill({juce::Colour(0xff626971),x-7,y-7,juce::Colour(0xff111418),x+7,y+7,false});g.fillEllipse(x-7,y-7,14,14);g.setColour(juce::Colour(0xff07090b));g.drawLine(x-4,y,x+4,y,1.5f);}
}

void DoziGlueLookAndFeel::drawRotarySlider(juce::Graphics&g,int x,int y,int width,int height,float position,float start,float end,juce::Slider&slider){
    auto area=juce::Rectangle<float>(static_cast<float>(x),static_cast<float>(y),static_cast<float>(width),static_cast<float>(height)).reduced(9);const auto radius=std::min(area.getWidth(),area.getHeight())*.34f;const auto centre=area.getCentre();
    for(int tick=0;tick<31;++tick){const auto angle=start+(end-start)*tick/30.0f;const auto inner=centre+juce::Point<float>(std::sin(angle),-std::cos(angle))*(radius+8);const auto outer=centre+juce::Point<float>(std::sin(angle),-std::cos(angle))*(radius+12);g.setColour(tick%5==0?cream:cream.withAlpha(.45f));g.drawLine({inner,outer},tick%5==0?1.5f:1.0f);}
    g.setGradientFill({juce::Colour(0xff59616a),centre.x-radius,centre.y-radius,juce::Colour(0xff090b0e),centre.x+radius,centre.y+radius,false});g.fillEllipse(centre.x-radius,centre.y-radius,radius*2,radius*2);g.setColour(juce::Colour(0xff030405));g.drawEllipse(centre.x-radius,centre.y-radius,radius*2,radius*2,3);
    for(int ring=0;ring<5;++ring){g.setColour(juce::Colours::white.withAlpha(.025f));g.drawEllipse(centre.x-radius+ring*3,centre.y-radius+ring*3,(radius-ring*3)*2,(radius-ring*3)*2,1);}
    const auto angle=start+position*(end-start);const auto tip=centre+juce::Point<float>(std::sin(angle),-std::cos(angle))*(radius*.78f);g.setColour(cream);g.drawLine(centre.x,centre.y,tip.x,tip.y,3.0f);g.setColour(cyan.withAlpha(.7f));g.fillEllipse(tip.x-2.5f,tip.y-2.5f,5,5);
    g.setColour(cyan);g.setFont(juce::FontOptions(12.0f).withStyle("Bold"));g.drawText(slider.getTextFromValue(slider.getValue()),area.removeFromBottom(18),juce::Justification::centred);
}
void DoziGlueLookAndFeel::drawToggleButton(juce::Graphics&g,juce::ToggleButton&button,bool over,bool down){auto area=button.getLocalBounds().toFloat().reduced(2);g.setGradientFill({juce::Colour(0xff3b4248),area.getX(),area.getY(),juce::Colour(0xff090c0f),area.getRight(),area.getBottom(),false});g.fillRoundedRectangle(area,5);g.setColour(over?cream:juce::Colour(0xff59626b));g.drawRoundedRectangle(area,5,1.5f);const auto lit=button.getToggleState();g.setColour(lit?amber:juce::Colour(0xff2d2418));g.fillEllipse(area.getRight()-13,area.getY()+7,6,6);g.setColour(cream.withAlpha(down?.7f:1.0f));g.setFont(juce::FontOptions(12.0f).withStyle("Bold"));g.drawFittedText(button.getButtonText(),button.getLocalBounds().reduced(6),juce::Justification::centred,2);}
void DoziGlueLookAndFeel::drawButtonBackground(juce::Graphics&g,juce::Button&button,const juce::Colour&,bool over,bool){auto area=button.getLocalBounds().toFloat().reduced(2);g.setGradientFill({juce::Colour(0xff414850),area.getX(),area.getY(),juce::Colour(0xff0a0d10),area.getRight(),area.getBottom(),false});g.fillRoundedRectangle(area,5);g.setColour(over?cream:juce::Colour(0xff59626b));g.drawRoundedRectangle(area,5,1.5f);}
void DoziGlueLookAndFeel::drawButtonText(juce::Graphics&g,juce::TextButton&button,bool,bool){g.setColour(cream);g.setFont(juce::FontOptions(12.0f).withStyle("Bold"));g.drawText(button.getButtonText(),button.getLocalBounds(),juce::Justification::centred);}

DoziGlueCompressorEditor::DoziGlueCompressorEditor(DoziGlueCompressorProcessor&p):AudioProcessorEditor(&p),glueProcessor(p){setSize(1180,620);setResizable(false,false);const std::array<juce::Component*,10>components{&threshold,&attack,&release,&ratio,&makeup,&inButton,&autoButton,&autoReleaseButton,&hpfButton,&resetButton};for(auto*component:components){addAndMakeVisible(component);component->setLookAndFeel(&lookAndFeel);}configureKnob(threshold,"THRESHOLD"," dBFS");configureKnob(attack,"ATTACK"," ms");configureKnob(release,"RELEASE"," ms");configureKnob(ratio,"RATIO",":1");configureKnob(makeup,"MAKEUP"," dB");inButton.setButtonText("IN\nBYPASS");autoButton.setButtonText("AUTO\nMAKEUP");autoReleaseButton.setButtonText("AUTO\nRELEASE");hpfButton.setButtonText("SC HPF\n80 Hz");for(auto*button:{&inButton,&autoButton,&autoReleaseButton,&hpfButton})button->setClickingTogglesState(true);const std::array<juce::Slider*,5>sliders{&threshold,&attack,&release,&ratio,&makeup};const std::array<const char*,5>sliderIds{"threshold","attack","release","ratio","makeupGainDb"};for(std::size_t n=0;n<sliders.size();++n)sliderAttachments[n]=std::make_unique<SliderAttachment>(glueProcessor.parameters,sliderIds[n],*sliders[n]);const std::array<juce::Button*,4>buttons{&inButton,&autoButton,&autoReleaseButton,&hpfButton};const std::array<const char*,4>buttonIds{"moduleEnabled","autoMakeup","autoRelease","sidechainHpf"};for(std::size_t n=0;n<buttons.size();++n)buttonAttachments[n]=std::make_unique<ButtonAttachment>(glueProcessor.parameters,buttonIds[n],*buttons[n]);resetButton.onClick=[this]{glueProcessor.resetParametersToDefaults();};autoReleaseButton.onStateChange=[this]{release.setEnabled(!autoReleaseButton.getToggleState());};release.setEnabled(!autoReleaseButton.getToggleState());startTimerHz(30);}
DoziGlueCompressorEditor::~DoziGlueCompressorEditor(){stopTimer();const std::array<juce::Component*,10>components{&threshold,&attack,&release,&ratio,&makeup,&inButton,&autoButton,&autoReleaseButton,&hpfButton,&resetButton};for(auto*component:components)component->setLookAndFeel(nullptr);}
void DoziGlueCompressorEditor::configureKnob(juce::Slider&slider,const char*name,const char*suffix){slider.setName(name);slider.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);slider.setTextBoxStyle(juce::Slider::NoTextBox,false,0,0);slider.setTextValueSuffix(suffix);slider.setDoubleClickReturnValue(true,0);}
void DoziGlueCompressorEditor::timerCallback(){const auto current=glueProcessor.meterSnapshot();for(std::size_t n=0;n<2;++n){displayed.inputDbfs[n]=current.inputDbfs[n]>displayed.inputDbfs[n]?current.inputDbfs[n]:std::max(-100.0f,displayed.inputDbfs[n]-2.5f);displayed.outputDbfs[n]=current.outputDbfs[n]>displayed.outputDbfs[n]?current.outputDbfs[n]:std::max(-100.0f,displayed.outputDbfs[n]-2.5f);displayed.gainReductionDb[n]=current.gainReductionDb[n]>displayed.gainReductionDb[n]?displayed.gainReductionDb[n]*.25f+current.gainReductionDb[n]*.75f:displayed.gainReductionDb[n]*.88f+current.gainReductionDb[n]*.12f;}repaint();}

void DoziGlueCompressorEditor::paint(juce::Graphics&g){auto bounds=getLocalBounds().toFloat();g.setGradientFill({juce::Colour(0xff323941),0,0,panel,bounds.getRight(),bounds.getBottom(),false});g.fillAll();for(int x=0;x<getWidth();x+=3){g.setColour(juce::Colours::white.withAlpha((x%11)*.0015f));g.drawVerticalLine(x,0,getHeight());}g.setColour(juce::Colour(0xff080c10));g.fillRect(0.0f,0.0f,38.0f,bounds.getHeight());g.fillRect(bounds.getRight()-38,0.0f,38.0f,bounds.getHeight());for(auto point:{juce::Point<float>{22,22},{bounds.getRight()-22,22},{22,bounds.getBottom()-22},{bounds.getRight()-22,bounds.getBottom()-22},{22,bounds.getCentreY()},{bounds.getRight()-22,bounds.getCentreY()}})screw(g,point.x,point.y);g.setColour(cream);g.setFont(juce::FontOptions(24.0f).withStyle("Bold"));g.drawText("D O Z I   /   G L U E   C O M P R E S S O R",80,18,getWidth()-160,34,juce::Justification::centred);g.setColour(juce::Colour(0xff4b565e));g.drawHorizontalLine(61,80,getWidth()-80);auto meterWindow=juce::Rectangle<float>(245,78,getWidth()-490,292);g.setColour(dark);g.fillRoundedRectangle(meterWindow,10);g.setColour(juce::Colour(0xff66717a));g.drawRoundedRectangle(meterWindow,10,2);paintLedMeter(g,{268,105,58,225},std::max(displayed.inputDbfs[0],displayed.inputDbfs[1]),"INPUT");paintLedMeter(g,{getWidth()-326.0f,105,58,225},std::max(displayed.outputDbfs[0],displayed.outputDbfs[1]),"OUTPUT");const auto vuWidth=(meterWindow.getWidth()-190)/2;paintVu(g,{348,105,vuWidth,190},displayed.gainReductionDb[0],"L");paintVu(g,{348+vuWidth+20,105,vuWidth,190},displayed.gainReductionDb[1],"R");g.setColour(cream);g.setFont(juce::FontOptions(13.0f));g.drawText("GAIN REDUCTION",meterWindow.getX(),302,meterWindow.getWidth(),20,juce::Justification::centred);g.setColour(cyan);g.setFont(juce::FontOptions(18.0f).withStyle("Bold"));g.drawText(juce::String((displayed.gainReductionDb[0]+displayed.gainReductionDb[1])*.5f,1)+" dB GR",meterWindow.getX(),324,meterWindow.getWidth(),25,juce::Justification::centred);g.setColour(juce::Colour(0xff5c646b));g.drawVerticalLine(getWidth()-185,405,getHeight()-35);const std::array<juce::Slider*,5>knobs{&threshold,&attack,&release,&ratio,&makeup};for(auto*knob:knobs){g.setColour(cream);g.setFont(juce::FontOptions(13.0f).withStyle("Bold"));g.drawText(knob->getName(),knob->getX(),knob->getY()-18,knob->getWidth(),18,juce::Justification::centred);}g.setColour(cream.withAlpha(.65f));g.setFont(juce::FontOptions(10.0f));g.drawText("LINKED STEREO DETECTOR",meterWindow.getX(),meterWindow.getBottom()+5,meterWindow.getWidth(),18,juce::Justification::centred);}

void DoziGlueCompressorEditor::paintLedMeter(juce::Graphics&g,juce::Rectangle<float>area,float value,const juce::String&label){static constexpr std::array<float,8>thresholds{12,6,0,-6,-12,-18,-24,-36};g.setColour(cream);g.setFont(juce::FontOptions(11.0f).withStyle("Bold"));g.drawText(label,area.removeFromTop(20),juce::Justification::centred);const auto h=(area.getHeight()-14)/8;for(std::size_t n=0;n<thresholds.size();++n){auto segment=juce::Rectangle<float>(area.getX()+17,area.getY()+n*(h+2),24,h);const auto lit=value>=thresholds[n];const auto colour=n<3?amber:cyan;g.setColour(lit?colour:colour.withAlpha(.12f));g.fillRoundedRectangle(segment,2);g.setColour(cream.withAlpha(.55f));g.setFont(juce::FontOptions(9.0f));g.drawText(juce::String(static_cast<int>(thresholds[n])),area.getX()-7,segment.getY(),22,h,juce::Justification::centredRight);}}
void DoziGlueCompressorEditor::paintVu(juce::Graphics&g,juce::Rectangle<float>area,float reduction,const juce::String&channel){g.setGradientFill({juce::Colour(0xffeadfc6),area.getX(),area.getY(),juce::Colour(0xffb7a98e),area.getRight(),area.getBottom(),false});g.fillRoundedRectangle(area,6);g.setColour(juce::Colour(0xff4c4030));g.drawRoundedRectangle(area,6,2);const auto centre=juce::Point<float>(area.getCentreX(),area.getBottom()+18);const auto radius=area.getWidth()*.46f;for(int n=0;n<=20;n+=2){const auto angle=juce::degreesToRadians(-55.0f+110.0f*n/20.0f);const auto inner=centre+juce::Point<float>(std::sin(angle),-std::cos(angle))*(radius-(n%4==0?11:6));const auto outer=centre+juce::Point<float>(std::sin(angle),-std::cos(angle))*radius;g.drawLine({inner,outer},n%4==0?1.4f:.8f);if(n%4==0)g.drawText(juce::String(n),juce::Rectangle<float>(outer.x-12,outer.y-18,24,16),juce::Justification::centred);}const auto angle=juce::degreesToRadians(-55.0f+110.0f*std::clamp(reduction,0.0f,20.0f)/20.0f);const auto tip=centre+juce::Point<float>(std::sin(angle),-std::cos(angle))*(radius-15);g.setColour(juce::Colour(0xffb51f24));g.drawLine(centre.x,centre.y,tip.x,tip.y,2.2f);g.setColour(juce::Colour(0xff3a3025));g.fillEllipse(centre.x-6,centre.y-6,12,12);g.setFont(juce::FontOptions(12.0f).withStyle("Bold"));g.drawText(channel,area.removeFromBottom(24),juce::Justification::centred);}
void DoziGlueCompressorEditor::resized(){const auto scale=getWidth()/1180.0f;auto set=[scale](juce::Component&c,int x,int y,int w,int h){c.setBounds(juce::roundToInt(x*scale),juce::roundToInt(y*scale),juce::roundToInt(w*scale),juce::roundToInt(h*scale));};set(inButton,76,150,120,110);set(autoButton,1010,100,100,58);set(resetButton,1010,172,100,48);const std::array<juce::Slider*,5>knobs{&threshold,&attack,&release,&ratio,&makeup};for(std::size_t n=0;n<knobs.size();++n)set(*knobs[n],70+static_cast<int>(n)*180,430,150,150);set(autoReleaseButton,1000,420,120,58);set(hpfButton,1000,500,120,58);}
